tail = """
    <script>
        lucide.createIcons();

        // Setup Tab System
        document.querySelectorAll('[data-tabs]').forEach(tabGroup => {
            const tabs = tabGroup.querySelectorAll('.tab-btn');
            tabs.forEach(tab => {
                tab.addEventListener('click', () => {
                    tabs.forEach(t => t.classList.remove('tab-active', 'text-white'));
                    tabs.forEach(t => t.classList.add('text-gray-400'));

                    tab.classList.remove('text-gray-400');
                    tab.classList.add('tab-active', 'text-white');

                    const targetId = tab.getAttribute('data-target');
                    const targetContainer = document.getElementById(tab.getAttribute('data-container'));
                    if (targetContainer) {
                        const contents = targetContainer.querySelectorAll('.tab-content');
                        contents.forEach(c => c.classList.remove('active'));
                        const t = document.getElementById(targetId);
                        if(t) t.classList.add('active');
                    }
                });
            });
        });

        // Watchlist Accordion toggle
        document.querySelectorAll('.watchlist-category-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                const target = document.getElementById(btn.getAttribute('data-target'));
                const icon = btn.querySelector('.chevron');
                if (target.style.display === 'none') {
                    target.style.display = 'block';
                    if(icon) icon.style.transform = 'rotate(0deg)';
                } else {
                    target.style.display = 'none';
                    if(icon) icon.style.transform = 'rotate(-90deg)';
                }
            });
        });

        // Toggle Buttons (like Ideas Video only)
        document.querySelectorAll('[data-toggle]').forEach(btn => {
            btn.addEventListener('click', () => {
                btn.classList.toggle('bg-cp-blue');
                btn.classList.toggle('text-white');
                btn.classList.toggle('bg-gray-800');
                btn.classList.toggle('text-gray-400');
            });
        });

    </script>
</body>
</html>
"""

